INSERT INTO `services_i18n` (`id`, `service_id`, `locale`, `slug`, `name`, `summary`, `content`, `image_alt`, `meta_title`, `meta_description`, `meta_keywords`) VALUES
('10000001-0000-4000-8000-010000000001', '10000000-0000-4000-8000-010000000001', 'tr', 'kurumsal-web-sitesi', 'Kurumsal web sitesi', 'Marka kimliğinizi, hizmetlerinizi ve iletişim akışlarınızı modern, hızlı ve SEO uyumlu bir kurumsal web sitesiyle yayına alırım.', '{"source":"faz1_extra","packages":[{"title":"Başlangıç","price":15000,"currency":"TRY","duration_days":10,"revisions":2,"features":["Kurumsal sayfalar","İletişim formu","SEO temel kurulumu"]},{"title":"Profesyonel","price":30000,"currency":"TRY","duration_days":20,"revisions":4,"features":["Çok dilli yapı","Admin panel","Blog ve referans alanları"]}],"html":"Kurumsal web sitesi; marka anlatımı, hizmet sayfaları, iletişim formları, hızlı frontend ve SEO/GEO uyumlu teknik kurulum ile teslim edilir."}', 'Kurumsal web sitesi', 'Kurumsal web sitesi | GZL Teknoloji', 'Modern, hızlı ve SEO uyumlu kurumsal web sitesi geliştirme hizmeti.', 'kurumsal web sitesi, web tasarım, GZL Teknoloji'),
('10000002-0000-4000-8000-010000000001', '10000000-0000-4000-8000-010000000001', 'en', 'corporate-website', 'Corporate website', 'A fast, multilingual and SEO-ready corporate website for your brand, services and lead flow.', '{"source":"faz1_extra","packages":[{"title":"Starter","price":15000,"currency":"TRY","duration_days":10,"revisions":2,"features":["Corporate pages","Contact form","SEO baseline"]},{"title":"Professional","price":30000,"currency":"TRY","duration_days":20,"revisions":4,"features":["Multilingual structure","Admin panel","Blog and references"]}],"html":"Corporate website delivery with brand pages, service pages, contact flows, performance-focused frontend and SEO/GEO-ready technical setup."}', 'Corporate website', 'Corporate website | GZL Technology', 'Fast and SEO-ready corporate website development service.', 'corporate website, web design, GZL Technology'),
('10000001-0000-4000-8000-010000000002', '10000000-0000-4000-8000-010000000002', 'tr', 'e-ticaret-sitesi', 'E-ticaret sitesi', 'Ürün, kategori, sepet, ödeme ve admin panel akışlarını kapsayan ölçeklenebilir e-ticaret sitesi geliştiririm.', '{"source":"faz1_extra","packages":[{"title":"Başlangıç","price":30000,"currency":"TRY","duration_days":20,"revisions":3,"features":["Ürün/kategori yönetimi","Sepet akışı","Ödeme altyapısı hazırlığı"]},{"title":"Kurumsal","price":75000,"currency":"TRY","duration_days":45,"revisions":6,"features":["Çok mağazalı yapı","Kampanya/kupon","ERP entegrasyonu"]}],"html":"E-ticaret sitesi; ürün yönetimi, kategori yapısı, sepet, ödeme altyapısı, sipariş takibi ve admin paneli ile geliştirilir."}', 'E-ticaret sitesi', 'E-ticaret sitesi | GZL Teknoloji', 'Next.js ve Fastify tabanlı e-ticaret sitesi geliştirme hizmeti.', 'e-ticaret sitesi, online satış, GZL Teknoloji'),
('10000002-0000-4000-8000-010000000002', '10000000-0000-4000-8000-010000000002', 'en', 'e-commerce-website', 'E-commerce website', 'A scalable e-commerce website with product, category, cart, payment and admin workflows.', '{"source":"faz1_extra","packages":[{"title":"Starter","price":30000,"currency":"TRY","duration_days":20,"revisions":3,"features":["Product/category management","Cart flow","Payment setup readiness"]},{"title":"Enterprise","price":75000,"currency":"TRY","duration_days":45,"revisions":6,"features":["Multi-store structure","Campaigns/coupons","ERP integration"]}],"html":"E-commerce website development with product management, categories, cart, payment setup, order tracking and admin panel."}', 'E-commerce website', 'E-commerce website | GZL Technology', 'Next.js and Fastify based e-commerce website development.', 'e-commerce website, online sales, GZL Technology'),
('10000001-0000-4000-8000-010000000003', '10000000-0000-4000-8000-010000000003', 'tr', 'ozel-yazilim-nextjs-fastify', 'Özel yazılım (Next.js + Fastify)', 'İş sürecinize özel panel, entegrasyon, otomasyon veya SaaS MVP geliştirmelerini Next.js + Fastify stack ile kurarım.', '{"source":"faz1_extra","packages":[{"title":"MVP","price":50000,"currency":"TRY","duration_days":30,"revisions":4,"features":["Analiz ve veri modeli","API ve frontend","Temel admin panel"]},{"title":"Ölçeklenebilir","price":120000,"currency":"TRY","duration_days":60,"revisions":8,"features":["Rol/izin mimarisi","Entegrasyonlar","Docker deploy"]}],"html":"Özel yazılım; ihtiyaç analizi, veri modeli, Fastify API, Next.js arayüz, admin panel, entegrasyon ve deploy adımlarıyla uygulanır."}', 'Özel yazılım', 'Özel yazılım (Next.js + Fastify) | GZL Teknoloji', 'Next.js ve Fastify ile özel yazılım, panel, otomasyon ve SaaS MVP geliştirme.', 'özel yazılım, Next.js, Fastify, SaaS MVP'),
('10000002-0000-4000-8000-010000000003', '10000000-0000-4000-8000-010000000003', 'en', 'custom-software-nextjs-fastify', 'Custom software (Next.js + Fastify)', 'Custom panels, integrations, automation flows or SaaS MVPs built with the Next.js + Fastify stack.', '{"source":"faz1_extra","packages":[{"title":"MVP","price":50000,"currency":"TRY","duration_days":30,"revisions":4,"features":["Analysis and data model","API and frontend","Basic admin panel"]},{"title":"Scalable","price":120000,"currency":"TRY","duration_days":60,"revisions":8,"features":["Role/permission model","Integrations","Docker deploy"]}],"html":"Custom software delivery covering analysis, data model, Fastify API, Next.js interface, admin panel, integrations and deployment."}', 'Custom software', 'Custom software (Next.js + Fastify) | GZL Technology', 'Custom software, panel, automation and SaaS MVP development with Next.js and Fastify.', 'custom software, Next.js, Fastify, SaaS MVP'),
('10000001-0000-4000-8000-010000000004', '10000000-0000-4000-8000-010000000004', 'tr', 'bakim-destek', 'Bakım-destek', 'Canlı siteler ve uygulamalar için güncelleme, hata düzeltme, performans, yedekleme ve küçük geliştirme desteği sağlarım.', '{"source":"faz1_extra","packages":[{"title":"Aylık Bakım","price":5000,"currency":"TRY","duration_days":30,"revisions":2,"features":["Haftalık kontrol","Küçük hata düzeltmeleri","Yedek ve izleme"]},{"title":"Gelişim Desteği","price":15000,"currency":"TRY","duration_days":30,"revisions":4,"features":["Yeni küçük özellikler","Performans iyileştirme","Aylık rapor"]}],"html":"Bakım-destek; canlı sistemlerin düzenli kontrolü, güvenlik güncellemeleri, hata düzeltmeleri, performans takibi ve küçük geliştirmelerini kapsar."}', 'Bakım-destek', 'Bakım-destek | GZL Teknoloji', 'Canlı site ve uygulamalar için teknik bakım, destek ve performans hizmeti.', 'bakım destek, web bakım, teknik destek'),
('10000002-0000-4000-8000-010000000004', '10000000-0000-4000-8000-010000000004', 'en', 'maintenance-support', 'Maintenance and support', 'Updates, bug fixes, performance checks, backups and small improvements for live websites and applications.', '{"source":"faz1_extra","packages":[{"title":"Monthly Care","price":5000,"currency":"TRY","duration_days":30,"revisions":2,"features":["Weekly checks","Small bug fixes","Backup and monitoring"]},{"title":"Growth Support","price":15000,"currency":"TRY","duration_days":30,"revisions":4,"features":["Small new features","Performance improvements","Monthly report"]}],"html":"Maintenance and support covers regular checks, security updates, bug fixes, performance monitoring and small improvements for live systems."}', 'Maintenance and support', 'Maintenance and support | GZL Technology', 'Technical maintenance, support and performance service for live websites and applications.', 'maintenance support, web care, technical support')
