INSERT INTO `faqs_i18n` (`id`, `faq_id`, `locale`, `question`, `answer`, `slug`) VALUES
('50000001-0000-4000-8000-010000000001', '50000000-0000-4000-8000-010000000001', 'tr', 'Teklif süreci nasıl ilerliyor?', 'Önce ihtiyaç ve kapsam netleştirilir, ardından paket veya özel teklif hazırlanır. Onay sonrası geliştirme, test ve teslim adımları planlanır.', 'teklif-sureci-nasil-ilerliyor'),
('50000002-0000-4000-8000-010000000001', '50000000-0000-4000-8000-010000000001', 'en', 'How does the offer process work?', 'First the scope and requirements are clarified, then a package or custom quote is prepared. After approval, development, testing and delivery are scheduled.', 'how-does-the-offer-process-work'),
('50000001-0000-4000-8000-010000000002', '50000000-0000-4000-8000-010000000002', 'tr', 'Projeler hangi teknolojilerle geliştiriliyor?', 'Kurumsal web ve SaaS projelerinde ağırlıklı olarak Next.js, React, TypeScript, Fastify, MySQL ve Docker kullanılır.', 'projeler-hangi-teknolojilerle-gelistiriliyor'),
('50000002-0000-4000-8000-010000000002', '50000000-0000-4000-8000-010000000002', 'en', 'Which technologies are used?', 'Corporate websites and SaaS projects are usually built with Next.js, React, TypeScript, Fastify, MySQL and Docker.', 'which-technologies-are-used'),
('50000001-0000-4000-8000-010000000003', '50000000-0000-4000-8000-010000000003', 'tr', 'Teslimden sonra destek var mı?', 'Evet. Bakım-destek paketleriyle hata düzeltme, performans kontrolü, yedekleme ve küçük geliştirme desteği sağlanır.', 'teslimden-sonra-destek-var-mi'),
('50000002-0000-4000-8000-010000000003', '50000000-0000-4000-8000-010000000003', 'en', 'Is there support after delivery?', 'Yes. Maintenance packages cover bug fixes, performance checks, backups and small improvements after delivery.', 'is-there-support-after-delivery'),
('50000001-0000-4000-8000-010000000004', '50000000-0000-4000-8000-010000000004', 'tr', 'Çok dilli site yapılabilir mi?', 'Evet. TR/EN başta olmak üzere çok dilli içerik, SEO metadata, sitemap ve hreflang yapısı kurulabilir.', 'cok-dilli-site-yapilabilir-mi'),
('50000002-0000-4000-8000-010000000004', '50000000-0000-4000-8000-010000000004', 'en', 'Can the website be multilingual?', 'Yes. Multilingual content, SEO metadata, sitemap and hreflang structure can be implemented, starting with TR/EN.', 'can-the-website-be-multilingual')
